"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, X, Clock, Calendar as CalIcon } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  
  // Form State
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [startTime, setStartTime] = useState("09:00");
  const [endTime, setEndTime] = useState("10:00");
  const [type, setType] = useState("agenda");

  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      if (item.startDatetime) {
        const d = new Date(item.startDatetime);
        const dateKey = format(d, "yyyy-MM-dd");
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    return map;
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    try {
      const res = await createCalendarItem({
        titel: title,
        documentType: type,
        datum: format(selectedDate, "yyyy-MM-dd"),
        startTime,
        endTime
      });

      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh();
        setTimeout(() => window.location.reload(), 300);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1400px] mx-auto p-4 text-white font-sans">
      {/* Üst Kısım / Ay Seçimi */}
      <div className="flex justify-between items-center mb-6 bg-[#121212] p-4 rounded-2xl border border-white/5 shadow-xl">
        <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-2 hover:bg-white/5 rounded-full transition-all"><ChevronLeft size={24} className="text-fuchsia-500"/></button>
        <h2 className="text-xl font-bold tracking-tight uppercase italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</h2>
        <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-2 hover:bg-white/5 rounded-full transition-all"><ChevronRight size={24} className="text-fuchsia-500"/></button>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-7 gap-px bg-white/10 border border-white/10 rounded-3xl overflow-hidden shadow-2xl">
        {["MA", "DI", "WO", "DO", "VR", "ZA", "ZO"].map(d => (
          <div key={d} className="bg-[#0a0a0a] py-3 text-center text-[10px] font-bold text-white/30 tracking-[0.2em]">{d}</div>
        ))}
        {(() => {
          const days = [];
          let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
          const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

          while (day <= endDate) {
            const dateKey = format(day, "yyyy-MM-dd");
            const dayTasks = taskMap[dateKey] || [];
            const isCurrentMonth = isSameMonth(day, currentMonth);
            const d = day;

            days.push(
              <div 
                key={day.toString()} 
                onClick={() => setSelectedDate(d)}
                className={`min-h-[130px] bg-[#0a0a0a] p-2 hover:bg-fuchsia-500/[0.03] transition-all cursor-pointer relative ${!isCurrentMonth ? "opacity-20" : ""}`}
              >
                <div className="text-[11px] font-mono text-white/40 mb-1">{format(day, "d")}</div>
                <div className="space-y-1">
                  {dayTasks.map((t: any) => (
                    <div key={t.id} className="text-[9px] p-1.5 bg-fuchsia-600/10 border-l-2 border-fuchsia-500 rounded-r text-fuchsia-100 leading-tight">
                      <div className="font-bold truncate">{t.title}</div>
                      <div className="opacity-60 font-mono text-[8px]">
                        {format(new Date(t.startDatetime), "HH:mm")} - {format(new Date(t.endDatetime), "HH:mm")}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
            day = addDays(day, 1);
          }
          return days;
        })()}
      </div>

      {/* iPHONE TARZI MODAL */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-md p-4">
          <div className="bg-[#1c1c1e] w-full max-w-md rounded-t-[30px] sm:rounded-[30px] p-6 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] border border-white/10 animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1 bg-white/20 rounded-full mx-auto mb-6 sm:hidden" />
            
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-white italic tracking-tight">Etkinlik Ekle</h3>
              <button onClick={() => setSelectedDate(null)} className="p-2 bg-white/5 rounded-full text-white/40 hover:text-white transition-all"><X size={20}/></button>
            </div>

            <div className="space-y-4">
              {/* Başlık Girişi */}
              <input 
                placeholder="Başlık" 
                value={title} onChange={(e) => setTitle(e.target.value)}
                className="w-full bg-[#2c2c2e] border-none p-4 rounded-2xl text-white placeholder:text-white/20 outline-none focus:ring-2 ring-fuchsia-500/50 transition-all"
              />

              {/* Zaman Seçici Alanı */}
              <div className="bg-[#2c2c2e] rounded-2xl overflow-hidden divide-y divide-white/5">
                <div className="flex items-center justify-between p-4">
                  <span className="text-sm font-medium text-white/60">Başlangıç</span>
                  <input 
                    type="time" 
                    value={startTime} onChange={(e) => setStartTime(e.target.value)}
                    className="bg-[#3a3a3c] text-white px-3 py-1 rounded-lg outline-none font-mono text-sm"
                  />
                </div>
                <div className="flex items-center justify-between p-4">
                  <span className="text-sm font-medium text-white/60">Bitiş</span>
                  <input 
                    type="time" 
                    value={endTime} onChange={(e) => setEndTime(e.target.value)}
                    className="bg-[#3a3a3c] text-white px-3 py-1 rounded-lg outline-none font-mono text-sm"
                  />
                </div>
              </div>

              {/* Kategori Seçimi (Yatay Scroll) */}
              <div className="flex gap-2 overflow-x-auto py-2 no-scrollbar">
                {['agenda', 'assignment', 'meeting', 'daily'].map(cat => (
                  <button 
                    key={cat} 
                    onClick={() => setType(cat)}
                    className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap border transition-all ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white shadow-lg shadow-fuchsia-500/20' : 'bg-transparent border-white/10 text-white/40'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>

              {/* Onay Butonu */}
              <button 
                onClick={handleSave} 
                disabled={loading || !title}
                className="w-full bg-white text-black font-black py-4 rounded-2xl uppercase text-[11px] tracking-[0.2em] mt-2 active:scale-95 transition-all disabled:opacity-20"
              >
                {loading ? "KAYDEDİLİYOR..." : "EKLE"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}